# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: digest
def digest(xs, offset=4):
    return [v + offset for v in xs]

# region: intake
def intake(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(intake(digest(sift(emit(raw)))))

